    private static List<object> TetrominoCells(int shape, int rotation, int x, int y)
    {
        int r = ((rotation % 4) + 4) % 4;
        (int dx, int dy)[] offsets;
        switch (shape)
        {
            case 0:
                offsets = (r == 1 || r == 3)
