                    default: offsets = new (int, int)[] { (2,0), (0,1), (1,1), (2,1) }; break;
                }
                break;
        }
        var result = new List<object>();
        foreach (var (dx, dy) in offsets)
            result.Add(new PointF(x + dx, y + dy));
        return result;
    }

