            if ((countInRow >= 10))
            {
                newBoard = new List<object>();
                foreach (var cell in board)
                {
                    if ((((PointF)cell).Y != row))
                    {
                        if ((((PointF)cell).Y < row))
                        {
                            newBoard.Add(new PointF((float)(((PointF)cell).X), (float)((((PointF)cell).Y + 1))));
                        }
                        if ((((PointF)cell).Y > row))
                        {
